//! Lightweight account metadata helpers for client-side instruction builders.
//!
//! Pina deliberately does not convert native schema values into raw
//! instruction bytes. Instruction data is initialized in caller-owned storage
//! through the zero-copy companion generated by `zeropod`.

use crate::Address;

/// An account metadata tuple of `(address, is_signer, is_writable)`.
pub type AccountMetaTuple = (Address, bool, bool);

/// Creates metadata for an address that is both a signer and writable.
#[inline]
pub fn writable_signer(address: &Address) -> AccountMetaTuple {
	(*address, true, true)
}

/// Creates metadata for an address that is writable but not a signer.
#[inline]
pub fn writable(address: &Address) -> AccountMetaTuple {
	(*address, false, true)
}

/// Creates metadata for an address that is a signer but read-only.
#[inline]
pub fn readonly_signer(address: &Address) -> AccountMetaTuple {
	(*address, true, false)
}

/// Creates metadata for an address that is neither a signer nor writable.
#[inline]
pub fn readonly(address: &Address) -> AccountMetaTuple {
	(*address, false, false)
}

#[cfg(test)]
mod tests {
	use super::*;

	#[test]
	fn metadata_helpers_preserve_address_and_flags() {
		let address = Address::from([7u8; 32]);
		assert_eq!(writable_signer(&address), (address, true, true));
		assert_eq!(writable(&address), (address, false, true));
		assert_eq!(readonly_signer(&address), (address, true, false));
		assert_eq!(readonly(&address), (address, false, false));
	}
}
